  final Value<String> productoCodigo;
  final Value<DateTime> fechaVigencia;
  final Value<double> precio;
  final Value<double> costoUnidad;
  final Value<double?> margenPct;
  final Value<int> rowid;
  const PriceHistoryCompanion({
    this.id = const Value.absent(),
    this.productoCodigo = const Value.absent(),
    this.fechaVigencia = const Value.absent(),
    this.precio = const Value.absent(),
    this.costoUnidad = const Value.absent(),
    this.margenPct = const Value.absent(),
    this.rowid = const Value.absent(),
  });
  PriceHistoryCompanion.insert({
    required String id,
    required String productoCodigo,
    required DateTime fechaVigencia,
    required double precio,
    required double costoUnidad,
    this.margenPct = const Value.absent(),
    this.rowid = const Value.absent(),
  }) : id = Value(id),
       productoCodigo = Value(productoCodigo),
       fechaVigencia = Value(fechaVigencia),
       precio = Value(precio),
       costoUnidad = Value(costoUnidad);
  static Insertable<PriceHistoryData> custom({
    Expression<String>? id,
    Expression<String>? productoCodigo,
    Expression<DateTime>? fechaVigencia,
    Expression<double>? precio,
    Expression<double>? costoUnidad,
    Expression<double>? margenPct,
    Expression<int>? rowid,
  }) {
    return RawValuesInsertable({
      if (id != null) 'id': id,
      if (productoCodigo != null) 'producto_codigo': productoCodigo,
      if (fechaVigencia != null) 'fecha_vigencia': fechaVigencia,
      if (precio != null) 'precio': precio,
      if (costoUnidad != null) 'costo_unidad': costoUnidad,
      if (margenPct != null) 'margen_pct': margenPct,
      if (rowid != null) 'rowid': rowid,
    });
  }

  PriceHistoryCompanion copyWith({
    Value<String>? id,
    Value<String>? productoCodigo,
    Value<DateTime>? fechaVigencia,
    Value<double>? precio,
    Value<double>? costoUnidad,
    Value<double?>? margenPct,
    Value<int>? rowid,
  }) {
    return PriceHistoryCompanion(
      id: id ?? this.id,
      productoCodigo: productoCodigo ?? this.productoCodigo,
      fechaVigencia: fechaVigencia ?? this.fechaVigencia,
      precio: precio ?? this.precio,
      costoUnidad: costoUnidad ?? this.costoUnidad,
      margenPct: margenPct ?? this.margenPct,
      rowid: rowid ?? this.rowid,
    );
  }

  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    if (id.present) {
      map['id'] = Variable<String>(id.value);
    }
    if (productoCodigo.present) {
      map['producto_codigo'] = Variable<String>(productoCodigo.value);
    }
    if (fechaVigencia.present) {
      map['fecha_vigencia'] = Variable<DateTime>(fechaVigencia.value);
    }
    if (precio.present) {
      map['precio'] = Variable<double>(precio.value);
    }
    if (costoUnidad.present) {
      map['costo_unidad'] = Variable<double>(costoUnidad.value);
    }
    if (margenPct.present) {
      map['margen_pct'] = Variable<double>(margenPct.value);
    }
    if (rowid.present) {
      map['rowid'] = Variable<int>(rowid.value);
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('PriceHistoryCompanion(')
          ..write('id: $id, ')
          ..write('productoCodigo: $productoCodigo, ')
          ..write('fechaVigencia: $fechaVigencia, ')
          ..write('precio: $precio, ')
          ..write('costoUnidad: $costoUnidad, ')
          ..write('margenPct: $margenPct, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

