    final map = <String, Expression>{};
    map['fecha'] = Variable<String>(fecha);
    map['total_ventas'] = Variable<double>(totalVentas);
    map['ventas_efectivo'] = Variable<double>(ventasEfectivo);
    map['ventas_transferencia'] = Variable<double>(ventasTransferencia);
    map['costo_produccion'] = Variable<double>(costoProduccion);
    map['total_gastos'] = Variable<double>(totalGastos);
