    map['utilidad_neta'] = Variable<double>(utilidadNeta);
    map['distribucion_yurdenis'] = Variable<double>(distribucionYurdenis);
    map['distribucion_mildrey'] = Variable<double>(distribucionMildrey);
    map['distribucion_negocio'] = Variable<double>(distribucionNegocio);
    return map;
  }

  DailySummariesCompanion toCompanion(bool nullToAbsent) {
    return DailySummariesCompanion(
      fecha: Value(fecha),
      totalVentas: Value(totalVentas),
      ventasEfectivo: Value(ventasEfectivo),
      ventasTransferencia: Value(ventasTransferencia),
      costoProduccion: Value(costoProduccion),
      totalGastos: Value(totalGastos),
      totalCompras: Value(totalCompras),
      utilidadNeta: Value(utilidadNeta),
      distribucionYurdenis: Value(distribucionYurdenis),
